// ===== STOCK PRICE SIMULATOR GUIDES (content only, no logic) =====
// Every input has a guide with the same parts: what it is, why analysts calculate it, where to find the figures,
// how to calculate it (with the formula), how to build a reasonable forecast, how it moves the projected price,
// a numerical example, common mistakes, sources, and optional analyst research notes. Examples say whether
// their figures come from a named filing or are illustrative arithmetic.
const SimHelp = (() => {
  const S = Object.assign({}, (typeof CompsHelp !== 'undefined' ? CompsHelp.S : {}), {
    edgarFts: ['SEC EDGAR full-text search (search 10-K and 10-Q text)', 'https://www.sec.gov/edgar/search/', 'raw'],
    secApi: ['SEC: EDGAR application programming interfaces (company facts and submissions files)', 'https://www.sec.gov/search-filings/edgar-application-programming-interfaces', 'method'],
    cfaMult: ['CFA Institute refresher reading: Market-Based Valuation: Price and Enterprise Value Multiples', 'https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/market-based-valuation-price-enterprise-value-multiples', 'method'],
    damCh18: ['Damodaran, Investment Valuation, chapter 18: earnings multiples (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch18.pdf', 'method'],
    damCh20: ['Damodaran, Investment Valuation, chapter 20: revenue and sector-specific multiples (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch20.pdf', 'method'],
    damPE: ['Damodaran: price-earnings ratios by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/pedata.html', 'direct'],
    damPS: ['Damodaran: price-to-sales and EV/sales ratios by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/psdata.html', 'direct'],
    damEbitda: ['Damodaran: EV/EBITDA, EV/EBIT and other value multiples by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/vebitda.html', 'direct'],
    damMargin: ['Damodaran: operating and net margins by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/margin.html', 'direct'],
    damGrowth: ['Damodaran: fundamental growth rates in EBIT by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/fundgrEB.html', 'direct'],
    damData: ['Damodaran Online: current data sets (multiples, margins, growth, by industry)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datacurrent.html', 'direct'],
    damOptions: ['Damodaran: management options and dilution', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/valquestions/mgtoption.htm', 'method'],
    secNonGaap: ['SEC staff interpretations: Non-GAAP financial measures (adjusted EBITDA, adjusted EPS)', 'https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/non-gaap-financial-measures', 'method'],
    amzn10k: ['Amazon 2025 Form 10-K (accession 0001018724-26-000004)', 'https://www.sec.gov/Archives/edgar/data/1018724/000101872426000004/amzn-20251231.htm', 'direct'],
    amzn10q: ['Amazon Q3 2026 Form 10-Q (accession 0001018724-26-000040)', 'https://www.sec.gov/Archives/edgar/data/1018724/000101872426000040/amzn-20260930.htm', 'direct'],
    ifrs16: ['IFRS Foundation: IFRS 16 Leases', 'https://www.ifrs.org/issued-standards/list-of-standards/ifrs-16-leases/', 'method'],
    fmp: ['Financial Modeling Prep API documentation (quotes, statements, estimates)', 'https://site.financialmodelingprep.com/developer/docs', 'method'],
    yahoo: ['Yahoo Finance quote page (price, dividends, split history)', 'https://finance.yahoo.com/', 'direct'],
  });
  const ILL = 'Illustrative arithmetic, not company data.';
  const G = {};
  const g = (k, o) => { G[k] = o; };

  // ---------- starting figures ----------
  g('price', { t: 'Current share price', what: 'The price of one common share on a stated date. It is the starting point that every projected price and return is measured against.',
    why: 'Upside, annualised return and total return are all ratios to today\'s price. Today\'s price also gives today\'s multiples (P/E, EV/EBITDA), which are the most common anchor for future multiples.',
    find: 'A market data provider (Financial Modeling Prep, Yahoo Finance, Bloomberg). SEC filings do not contain current prices. Use a closing price and record its date.',
    calc: 'Not calculated. Record the closing price and its date. If the price is for a different share class or an ADR, make sure the share count matches the same class.',
    forecast: 'Not forecast. The future price is the output of the simulator; the current price is an observation.',
    effect: 'A higher current price lowers every upside and return figure but does not change the projected price itself (except through the "hold today\'s multiple" starting point).',
    ex: 'If the price is $220.00 and the projected year-5 price is $348.13, the price return is 348.13 ÷ 220.00 − 1 = 58.2%. ' + ILL,
    mistakes: ['Using a price from a different date than the share count and financials without noticing.', 'Mixing an ADR price with the share count of the underlying ordinary shares.', 'Using an intraday price for one model and closing prices elsewhere.'],
    src: ['yahoo', 'fmp'], research: 'Prices move every day: a model with a price a month old can show a very different upside. When you compare this simulator with the DCF and Trading Comps, check that all three use the same price date (the comparison page shows each date).' });
  g('shares', { t: 'Shares outstanding and the diluted share count', what: 'Basic shares are the common shares in issue on a date (10-Q or 10-K cover page). The diluted count adds the shares that options, RSUs, warrants and convertibles would add (the net dilutive shares from the EPS note).',
    why: 'Price per share = equity value ÷ shares. EPS = net income ÷ diluted weighted-average shares. Too few shares overstate every per-share figure.',
    find: 'Basic: cover page of the newest 10-Q/10-K ("As of [date], there were N shares outstanding"). Net dilutive shares: the EPS note ("dilutive effect of stock-based awards"), or diluted minus basic weighted-average shares. In SEC data: dei:EntityCommonStockSharesOutstanding and the WeightedAverageNumber… concepts.',
    calc: 'Diluted shares = basic shares + net dilutive shares. Convert to millions (raw shares ÷ 1,000,000). The simulator then grows the count each year by the net share change.',
    forecast: 'The starting count is reported, not forecast. Its path is set by the "net share change" assumption (dilution from stock compensation minus buybacks).',
    effect: 'Doubling the share count halves the price per share for the same equity value. A 1% higher count lowers the price by about 1%.',
    ex: 'Amazon\'s Q3 2026 10-Q cover page lists 10,813,138,306 shares (10,813.1 million) as of October 21, 2026; its EPS note shows 132 million net dilutive shares for the quarter, so the diluted count is about 10,945 million (from the filing).',
    mistakes: ['Using weighted-average shares as today\'s count.', 'Forgetting a second share class (Class A + Class B).', 'Mixing pre-split and post-split counts (see Stock splits).'],
    src: ['amzn10q', 'edgarFts', 'damOptions'], research: 'The treasury stock method only counts in-the-money options, net of the shares bought back with the exercise proceeds, at the period\'s average price. When the price has moved a lot since the quarter, recompute it on the DCF\'s Share Dilution Guide.' });
  g('dilutive', { t: 'Net dilutive shares', what: 'The extra shares that stock options, RSUs, warrants and convertible securities add to the share count, as used in diluted EPS.',
    why: 'P/E and EPS projections use diluted EPS, so the share count must be diluted too. Otherwise price per share is overstated.',
    find: 'The EPS note of the latest 10-Q: "total dilutive effect of outstanding stock awards", or diluted weighted-average shares minus basic weighted-average shares.',
    calc: 'Net dilutive shares = diluted weighted-average shares − basic weighted-average shares (same quarter). Enter 0 if the company has a loss and reports no dilutive effect, and note that dilution will appear once it is profitable.',
    forecast: 'Not forecast here; future dilution is the net share change assumption.', effect: 'Adds to the starting share count, lowering every per-share figure proportionally.',
    ex: 'Amazon Q3 2026: diluted weighted-average shares 10,945mm − basic 10,813mm ≈ 132mm (from the 10-Q EPS note).',
    mistakes: ['Leaving it blank: the model needs a number (0 is allowed).', 'Counting anti-dilutive securities in a loss year.'], src: ['amzn10q', 'damOptions'],
    research: 'Loss-making companies report basic = diluted EPS because dilutive securities would reduce the loss per share. When projecting a return to profit, add the options and RSUs back (Share Dilution Guide in the DCF).' });
  g('rev', { t: 'Starting revenue', what: 'Total revenue (net sales) for the base period: the latest fiscal year (FY) or the trailing twelve months (TTM).',
    why: 'Every revenue-based projection compounds from this figure: Projected revenue = starting revenue × (1 + growth)^years.',
    find: 'Income statement of the 10-K (FY) or TTM = FY + year-to-date − prior year-to-date from the 10-Q. In SEC data: RevenueFromContractWithCustomerExcludingAssessedTax or Revenues.',
    calc: 'TTM revenue = latest fiscal year + current year-to-date − same period a year earlier.',
    forecast: 'Not forecast; it is reported. Choose FY or TTM with the base-period switch.', effect: 'Revenue-based prices move one-for-one with the starting revenue: 10% more starting revenue means about 10% more projected revenue, earnings and price.',
    ex: 'Amazon: FY2025 revenue 716,924 $mm (10-K); nine months to Sept. 30, 2026 584,069; nine months to Sept. 30, 2025 503,538 (Q3 2026 10-Q). TTM = 716,924 + 584,069 − 503,538 = 797,455 $mm (from the filings).',
    mistakes: ['Mixing TTM revenue with a fiscal-year margin from a different period.', 'Using gross bookings or GMV instead of reported revenue.', 'Entering thousands or units instead of $ millions.'],
    src: ['amzn10k', 'amzn10q', 'secApi'], research: 'A TTM base is more current but includes a mix of seasons; a FY base matches the 10-K. If the company has a 53-week year or an acquisition, adjust the base or note the effect on growth.' });
  g('ni', { t: 'Starting net income', what: 'Net income attributable to common shareholders for the base period.',
    why: 'Today\'s net margin (net income ÷ revenue) is the anchor for the forecast margin, and net income ÷ EPS checks that the share count and EPS are on the same split basis.',
    find: 'Income statement: "Net income" (attributable to the company, after noncontrolling interests). In SEC data: NetIncomeLoss.', calc: 'Net margin = net income ÷ revenue. TTM is built like revenue.',
    forecast: 'Not forecast directly: the P/E projection forecasts it as revenue × net margin.', effect: 'Only through the margin you choose.',
    ex: 'Amazon TTM to Sept. 30, 2026: net income 134,779 $mm on revenue 797,455 $mm = 16.9% net margin (from the filings). It includes large non-operating gains, so it is above the 13.1% operating margin.',
    mistakes: ['Using net income including noncontrolling interests (ProfitLoss).', 'Treating one-off gains (investment revaluations, tax benefits) as a recurring margin.'], src: ['amzn10q', 'secNonGaap'],
    research: 'When net income is above operating income, look for "other income (expense)" in the income statement: investment gains are rarely repeatable and should usually be left out of a forward net margin.' });
  g('eps', { t: 'Starting EPS (diluted)', what: 'Diluted earnings per share for the base period, as reported.', why: 'The EPS growth projection compounds from it, and price ÷ EPS gives today\'s P/E.',
    find: 'Income statement, "Diluted earnings per share". In SEC data: EarningsPerShareDiluted. TTM EPS = FY + YTD − prior YTD (approximate, because share counts change).',
    calc: 'Diluted EPS = net income to common ÷ diluted weighted-average shares.', forecast: 'Its future path is the EPS growth assumption.',
    effect: 'Projected price under the EPS method is proportional to it.', ex: 'Amazon FY2025 diluted EPS $7.17 on 77,670 $mm net income and 10,827mm diluted weighted-average shares (77,670 ÷ 10,827 = 7.17; from the 10-K).',
    mistakes: ['Using adjusted (non-GAAP) EPS with a GAAP P/E, or the other way round.', 'Growing a negative EPS by a percentage (it makes the loss bigger, not smaller).', 'Not adjusting EPS for a stock split since the period ended.'], src: ['amzn10k', 'secNonGaap'],
    research: 'Companies often guide on adjusted EPS. If you use it, use an adjusted P/E too (from the same data provider), and say so in the scenario rationale.' });
  g('ebitda', { t: 'Starting EBITDA', what: 'Earnings before interest, taxes, depreciation and amortisation: operating income + D&A, calculated from the filing.', why: 'Today\'s EBITDA margin anchors the forecast margin; EV ÷ EBITDA gives today\'s EV/EBITDA.',
    find: 'Operating income (income statement) + depreciation and amortisation (cash flow statement).', calc: 'EBITDA = operating income + D&A. Margin = EBITDA ÷ revenue.',
    forecast: 'Forecast as revenue × EBITDA margin.', effect: 'Through the EBITDA margin.', ex: 'Amazon TTM to Sept. 30, 2026: operating income 104,366 + D&A 79,353 = 183,719 $mm, a 23.0% margin (from the filings).',
    mistakes: ['Using a company\'s "adjusted EBITDA" (which adds back stock compensation) with a multiple built on reported EBITDA.', 'Comparing US GAAP EBITDA (operating lease cost inside) with IFRS EBITDA (lease cost outside).'], src: ['secNonGaap', 'ifrs16'],
    research: 'Stock-based compensation is a real cost: if you use adjusted EBITDA, the dilution assumption must carry the cost instead.' });
  g('ebit', { t: 'Starting operating income (EBIT)', what: 'Operating income as reported.', why: 'Anchors the operating margin and today\'s EV/EBIT.', find: 'Income statement, "Operating income". In SEC data: OperatingIncomeLoss.',
    calc: 'Operating margin = operating income ÷ revenue.', forecast: 'Forecast as revenue × operating margin.', effect: 'Through the operating margin.',
    ex: 'Amazon TTM: 104,366 ÷ 797,455 = 13.1% (from the filings).', mistakes: ['Including non-operating income (interest, investment gains).'], src: ['damMargin'],
    research: 'EV/EBIT is preferred to EV/EBITDA for capital-intensive companies, because depreciation is a real, recurring cost of staying in business.' });
  g('fcf', { t: 'Starting free cash flow', what: 'Operating cash flow − capital expenditures for the base period.', why: 'Anchors the FCF margin used by the P/FCF method.',
    find: 'Cash flow statement: "Net cash provided by operating activities" and "Purchases of property and equipment".', calc: 'FCF = operating cash flow − capex. FCF margin = FCF ÷ revenue.',
    forecast: 'Forecast as revenue × FCF margin.', effect: 'Through the FCF margin (P/FCF method only).', ex: 'Amazon\'s TTM FCF was negative (−46,892 $mm) because capex exceeded operating cash flow during its data-centre build-out (from the filings); P/FCF cannot value it until the margin turns positive.',
    mistakes: ['Using a negative FCF with a P/FCF multiple.', 'Forgetting finance-lease principal payments for lease-heavy companies.'], src: ['secApi'], research: 'For companies in heavy investment phases, FCF understates steady-state cash generation; P/FCF is better used in later forecast years.' });
  g('cash', { t: 'Cash and short-term investments', what: 'Cash, cash equivalents and marketable securities on the latest balance sheet.', why: 'EV methods add cash back when converting enterprise value to equity value: equity = EV − debt − claims + cash.',
    find: 'Balance sheet of the newest 10-Q. In SEC data: CashAndCashEquivalentsAtCarryingValue and MarketableSecuritiesCurrent.', calc: 'Cash = cash and equivalents + short-term investments. Enter 0 if none.',
    forecast: 'Use "Change in cash" each year: cash builds from retained free cash flow and falls with buybacks, dividends and acquisitions.', effect: 'Each extra $1bn of cash adds $1bn ÷ shares to the EV-method price (P/E and P/S prices are not affected).',
    ex: '$10,000mm more cash with 1,000mm shares adds $10.00 per share to the EV/EBITDA price. ' + ILL,
    mistakes: ['Counting restricted cash or customer funds as free cash.', 'Changing cash without changing the share count when the cash funds buybacks (count the buyback in one place only).'], src: ['cfaMult'],
    research: 'If you forecast buybacks through the net share change, the cash spent on them should lower the cash forecast too; otherwise the same money is counted twice.' });
  g('debt', { t: 'Debt (and finance leases)', what: 'Short-term borrowings, the current portion of long-term debt, long-term debt and finance lease liabilities.', why: 'EV methods subtract debt to get equity value. A missing debt figure is not the same as no debt, so it must be entered (0 if none).',
    find: 'Balance sheet and debt note of the newest 10-Q. In SEC data: LongTermDebt, LongTermDebtNoncurrent, ShortTermBorrowings, FinanceLeaseLiability.', calc: 'Debt = short-term borrowings + current and non-current long-term debt + finance leases (+ operating leases if you treat them as debt).',
    forecast: 'Use "Change in debt" each year (new issuance positive, repayment negative).', effect: 'Each extra $1bn of debt removes $1bn ÷ shares from the EV-method price.',
    ex: 'EV 100,000 − debt 20,000 + cash 5,000 = equity 85,000 $mm; ÷ 1,000mm shares = $85.00. ' + ILL,
    mistakes: ['Counting operating leases in debt while using an EV/EBITDA multiple that excludes them (be consistent).', 'Using book equity instead of debt.'], src: ['ifrs16', 'cfaMult'],
    research: 'Under US GAAP operating lease cost sits inside EBITDA, so operating leases are normally left out of debt when using US EV/EBITDA multiples (the default here). Under IFRS 16 they are debt and lease cost is outside EBITDA.' });
  g('claims', { t: 'Other claims (noncontrolling interests, preferred)', what: 'Claims on the business ahead of common shareholders that are not debt: noncontrolling interests, preferred equity and other debt-like items.',
    why: 'Enterprise value belongs to all capital providers; only what is left after these claims belongs to common shareholders.', find: 'Balance sheet: "Noncontrolling interests", "Preferred stock". In SEC data: MinorityInterest, PreferredStockValue.',
    calc: 'Claims = NCI + preferred + other claims, held constant over the projection.', forecast: 'Held at today\'s value.', effect: 'Each $1bn of claims removes $1bn ÷ shares from the EV-method price.',
    ex: 'A subsidiary 20% owned by others with 5,000 $mm of book NCI reduces equity value by 5,000 $mm. ' + ILL, mistakes: ['Ignoring NCI when EBITDA includes 100% of a partly owned subsidiary.'], src: ['cfaMult'], research: 'Book NCI can be far below market value; for large stakes, estimate the market value of the minority share.' });
  g('dps', { t: 'Starting dividend per share', what: 'The annual dividend per share paid over the base period (or the current annualised rate).', why: 'Dividends are part of the investor\'s total return: total return = price return + dividends received.',
    find: 'The 10-K/10-Q equity note or dividend announcements (8-K). In SEC data: CommonStockDividendsPerShareDeclared. Quote pages list the forward annual rate.', calc: 'Annual DPS = quarterly dividend × 4 (for a regular quarterly payer).',
    forecast: 'Either grow DPS at a rate, or use a payout ratio of projected EPS.', effect: 'Dividends do not change the projected price; they add to total return and IRR.',
    ex: 'A $0.25 quarterly dividend is $1.00 a year; growing 5% a year it pays 1.05, 1.10, 1.16, 1.22, 1.28 over five years (5.80 in total). ' + ILL,
    mistakes: ['Counting special dividends as recurring.', 'Forgetting to adjust DPS for a stock split.'], src: ['yahoo', 'edgarFts'], research: 'A payout ratio above 100% of earnings cannot last without borrowing or a falling cash balance.' });
  g('base', { t: 'Base period: TTM or fiscal year', what: 'The twelve-month period the projection starts from: trailing twelve months (to the latest 10-Q) or the latest fiscal year (10-K).',
    why: 'Year 1 of the projection is the twelve months after the base period. A stale base period makes year 1 partly history.', find: 'Both are built from the SEC file on Company & Starting Financials.',
    calc: 'Projection year t ends t years after the base period end. The holding period for returns is measured from the price date: t − (price date − base period end).',
    forecast: 'Use TTM when the latest quarter is recent and representative; FY when the 10-K is new or the year has strong seasonality you want to keep.', effect: 'Changes the starting revenue, margins and the length of the holding period.',
    ex: 'TTM ends Sept. 30, 2026 and the price is from Oct. 31, 2026: 0.08 years have passed, so the year-5 price is 4.92 years from the price date. ' + ILL,
    mistakes: ['Mixing a TTM revenue with a FY margin.', 'Calling the year-5 price a "five-year" target when the base year is already a year old.'], src: ['secApi'], research: 'Tick "measure returns from the price date" (the default) so annualised returns use the real holding period.' });
  g('split', { t: 'Stock splits', what: 'A split changes the number of shares and the price per share by the same factor, with no change in value. A 4-for-1 split makes 1 share into 4.',
    why: 'Filings from before a split show pre-split EPS and share counts. Combining them with a post-split price makes the P/E and every per-share projection wrong by the split factor.', find: 'The company\'s 8-K or press release announcing the split, the 10-Q equity note, or a quote site\'s split history.',
    calc: 'Post-split EPS = pre-split EPS ÷ factor; post-split shares = pre-split shares × factor. The simulator applies the factor to EPS and dividends (and to shares if you choose "all share figures").',
    forecast: 'Not forecast. Future splits do not change value, so they are ignored.', effect: 'A missed 10-for-1 split makes the P/E look 10× too high or the projected price 10× too low.',
    ex: 'EPS of $20.00 reported before a 10-for-1 split is $2.00 post-split; at a $120 post-split price the P/E is 60×, not 6×. ' + ILL,
    mistakes: ['Applying the factor twice when the filing already restated EPS for the split (most later filings do).', 'Adjusting the share count but not EPS (or the other way round).'], src: ['edgarFts', 'yahoo'],
    research: 'The simulator compares net income ÷ EPS (the share count EPS implies) with the share count. A near-whole-number ratio such as 2×, 4× or 10× usually means a split between the two dates and raises a warning.' });

  // ---------- growth & profitability ----------
  g('revGrowth', { t: 'Annual revenue growth', what: 'The rate at which revenue grows each year of the projection.', why: 'Revenue growth drives every method except EPS growth. Projected revenue = starting revenue × (1 + growth)^years.',
    find: 'History: the company\'s 3- and 5-year revenue growth (shown as references). Outlook: management guidance in earnings calls, analyst consensus, industry growth (market research, Damodaran\'s industry data).',
    calc: 'Historical CAGR = (revenue now ÷ revenue n years ago)^(1/n) − 1. Year-over-year = revenue ÷ prior-year revenue − 1.',
    forecast: 'Start near recent growth and fade toward the industry or economy rate as the company gets bigger. Use per-year values for a fading path. Bear and Bull should reflect real risks and opportunities, not arbitrary ± points.',
    effect: 'Over five years, 12% instead of 8% growth raises year-5 revenue, earnings and price by (1.12 ÷ 1.08)^5 − 1 ≈ 19.9% when margins and multiples are unchanged.',
    ex: '100,000 $mm × 1.12^5 = 176,234 $mm of revenue in year 5. ' + ILL, formula: 'Revenue_t = Revenue_(t−1) × (1 + g_t)',
    mistakes: ['Extrapolating a peak growth year for ten years.', 'Ignoring that very high growth usually needs lower margins (investment) or more shares (stock compensation).', 'Using nominal growth for one company and real growth for another.'],
    src: ['damGrowth', 'damData'], research: 'Large companies rarely sustain growth far above the economy for long: base rates from studies of corporate growth show high-growth companies fade toward the average within 5–10 years. Ask what share of its market the company would need in year 10.' });
  g('netMargin', { t: 'Net profit margin', what: 'Net income as a share of revenue.', why: 'In the P/E projection, projected net income = revenue × net margin, so margin and growth together set earnings.',
    find: 'History: net income ÷ revenue for TTM, FY and a 5-year average (references). Industry: Damodaran\'s margin tables. Guidance: operating margin targets in investor presentations.',
    calc: 'Net margin = net income ÷ revenue.', forecast: 'Build from the operating margin: operating margin − interest × (1 − tax) − taxes. Move toward a sustainable level for mature companies; use a per-year path (the "fade" helper) for turnarounds.',
    effect: 'The year-n price under the P/E method is proportional to the year-n margin: 20% instead of 15% raises it by a third.', ex: 'Revenue 176,234 $mm × 15% = 26,435 $mm net income; ÷ 1,000mm shares = EPS $26.44; × 20 P/E = $528.70. ' + ILL,
    formula: 'Net income_t = Revenue_t × net margin_t', mistakes: ['Projecting a margin inflated by one-off gains.', 'A net margin above the operating margin without a reason.', 'Ignoring that interest costs rise with new debt.'], src: ['damMargin'],
    research: 'Margins mean-revert in competitive industries. A margin far above peers needs a durable advantage (brand, network effects, cost position) to persist.' });
  g('ebitdaMargin', { t: 'EBITDA margin', what: 'EBITDA as a share of revenue.', why: 'The EV/EBITDA projection uses projected EBITDA = revenue × EBITDA margin.', find: 'History references (TTM, FY, 5-year range); peers on Trading Comps; Damodaran\'s industry data.',
    calc: 'EBITDA margin = (operating income + D&A) ÷ revenue.', forecast: 'Usually the most stable margin; change it when mix, scale or pricing really changes.', effect: 'Proportional to EBITDA; the price changes by more than the margin because debt is fixed (leverage).',
    ex: 'Revenue 150,000 × 25% = EBITDA 37,500; × 12 = EV 450,000; − net debt 50,000 = equity 400,000; ÷ 2,000mm shares = $200.00. At 27%: EV 486,000, equity 436,000, $218.00 (+9% for an 8% margin change). ' + ILL,
    formula: 'EBITDA_t = Revenue_t × EBITDA margin_t', mistakes: ['Using adjusted EBITDA margins with reported-EBITDA multiples.', 'An EBITDA margin below the operating margin (impossible unless D&A is negative).'], src: ['damEbitda', 'secNonGaap'], research: 'Check the EBITDA margin against capital intensity: a high EBITDA margin with heavy capex can still mean low free cash flow.' });
  g('ebitMargin', { t: 'Operating (EBIT) margin', what: 'Operating income as a share of revenue.', why: 'The EV/EBIT projection uses projected EBIT = revenue × operating margin.', find: 'History references; segment margins in the 10-K; Damodaran margin tables.',
    calc: 'Operating margin = operating income ÷ revenue.', forecast: 'Consider operating leverage: fixed costs make the margin rise with scale and fall in downturns.', effect: 'Proportional to EBIT.',
    ex: 'Revenue 150,000 × 15% = 22,500 EBIT; × 18 EV/EBIT = 405,000 EV. ' + ILL, formula: 'EBIT_t = Revenue_t × operating margin_t', mistakes: ['Setting it above the EBITDA margin.'], src: ['damMargin'], research: 'Segment disclosures often show very different margins by business; mix shift can move the total margin even when each segment is stable.' });
  g('fcfMargin', { t: 'Free cash flow margin', what: 'Free cash flow (operating cash flow − capex) as a share of revenue.', why: 'Used by the P/FCF projection.', find: 'History references from the cash flow statement.',
    calc: 'FCF margin = (operating cash flow − capex) ÷ revenue.', forecast: 'Rises when an investment cycle ends; falls when the company expands capacity.', effect: 'Proportional to FCF and the P/FCF price.',
    ex: 'Revenue 150,000 × 10% = 15,000 FCF; × 25 P/FCF = 375,000 equity; ÷ 2,000 = $187.50. ' + ILL, formula: 'FCF_t = Revenue_t × FCF margin_t', mistakes: ['Using a negative FCF with a P/FCF multiple.'], src: ['damData'], research: 'Stock compensation is added back in operating cash flow, which flatters FCF; the dilution assumption should carry that cost.' });
  g('epsGrowth', { t: 'Earnings (EPS) growth', what: 'The annual growth rate of diluted EPS, used directly by the EPS growth projection.', why: 'A quick way to project earnings when you do not want to model revenue and margins separately. Projected EPS = starting EPS × (1 + EPS growth)^years.',
    find: 'History (3- and 5-year EPS CAGR references); analyst long-term EPS growth estimates; guidance.', calc: 'EPS CAGR = (EPS now ÷ EPS n years ago)^(1/n) − 1 (both positive).',
    forecast: 'EPS growth ≈ revenue growth + margin change + buyback effect. Check it against the P/E projection: the two should not tell very different stories.', effect: 'Over five years, 15% instead of 10% raises year-5 EPS and price by (1.15 ÷ 1.10)^5 − 1 ≈ 24.9% at the same P/E.',
    ex: '$5.00 × 1.15^5 = $10.06 EPS; × 25 P/E = $251.42. ' + ILL, formula: 'EPS_t = EPS_0 × (1 + g_EPS)^t', mistakes: ['Growing from a negative or near-zero EPS (the rate explodes or makes no sense).', 'Extrapolating a recovery year (EPS from a depressed base).'], src: ['damCh18'],
    research: 'EPS growth from a depressed base (a recovery after a loss year) is not repeatable. The simulator refuses to grow a negative starting EPS.' });
  g('dilution', { t: 'Net share change (dilution and buybacks)', what: 'The annual percentage change in diluted shares: positive for net issuance (stock compensation, acquisitions paid in stock, conversions), negative for net buybacks.',
    why: 'Per-share value depends on how many shares share it. 2% a year of dilution removes about 10% of per-share value over five years.', find: 'History: change in diluted weighted-average shares (reference); the cash flow statement for buybacks; the stock compensation note for grants.',
    calc: 'Net share change = shares this year ÷ shares last year − 1. Shares_t = shares_(t−1) × (1 + change). EPS uses the average of the start and end counts (weighted-average); EV and P/S methods use the end-of-year count.',
    forecast: 'Stock compensation as a share of the market value, minus buybacks the company can afford from free cash flow.', effect: 'Price falls roughly by the cumulative change: (1 + d)^n. At −2% a year for five years, the count is 9.6% lower and the price about 10.6% higher.',
    ex: '1,000mm × 1.02^5 = 1,104.1mm shares: 10.4% more shares, so price is about 1 ÷ 1.104 = 90.6% of the no-dilution price. ' + ILL, formula: 'Shares_t = Shares_(t−1) × (1 + d_t)',
    mistakes: ['Counting buybacks in the share count and also keeping the cash (double counting).', 'Ignoring dilution for a company paying heavily in stock.'], src: ['damOptions'],
    research: 'Buybacks only add per-share value when the shares are bought below their value; at a high price they transfer value to selling shareholders.' });
  g('cashChange', { t: 'Change in cash and investments (per year)', what: 'How much cash and short-term investments rise (+) or fall (−) each year, in $ millions.', why: 'EV methods add cash to equity value. Retained cash raises the EV-based price.',
    find: 'Your free cash flow forecast minus dividends, buybacks and acquisitions; or the cash line of the three-statement model.', calc: 'Cash_t = cash_(t−1) + change_t.',
    forecast: 'For a profitable company that does not return cash, roughly FCF − dividends − buybacks. 0 (the default) holds cash flat.', effect: '+$1bn cash = +$1bn ÷ shares on EV-method prices only.', ex: 'Cash 10,000 + 2,000 a year for five years = 20,000 $mm. ' + ILL,
    formula: 'Cash_t = Cash_(t−1) + ΔCash_t', mistakes: ['Adding cash that is spent on the buybacks already in the share count.'], src: ['cfaMult'], research: 'Holding cash flat is conservative for cash-generative companies and generous for cash-burning ones.' });
  g('debtChange', { t: 'Change in debt (per year)', what: 'New borrowing (+) or repayment (−) each year, in $ millions.', why: 'EV methods subtract debt from enterprise value.', find: 'Debt maturity table in the 10-K debt note; management\'s leverage targets; the three-statement model.',
    calc: 'Debt_t = debt_(t−1) + change_t.', forecast: 'Repay maturities if the company targets lower leverage; borrow if it funds buybacks or acquisitions with debt.', effect: '+$1bn debt = −$1bn ÷ shares on EV-method prices.', ex: 'Debt 20,000 − 1,000 a year = 15,000 $mm after five years. ' + ILL,
    formula: 'Debt_t = Debt_(t−1) + ΔDebt_t', mistakes: ['Raising debt without raising interest cost (net margin) in the P/E projection.'], src: ['cfaMult'], research: 'More debt makes the equity price more sensitive to the EV multiple: leverage magnifies both gains and losses.' });
  g('payout', { t: 'Dividend payout ratio', what: 'Dividends as a share of earnings.', why: 'With the payout method, DPS_t = EPS_t × payout ratio.', find: 'History: dividends paid ÷ net income; dividend policy statements in the 10-K.',
    calc: 'Payout = DPS ÷ EPS.', forecast: 'Mature companies are often stable at 30–60%; growth companies pay little or nothing.', effect: 'Adds dividends to total return; does not change the projected price (no reinvestment trade-off is modelled).',
    ex: 'EPS $10.00 × 40% = $4.00 DPS. ' + ILL, formula: 'DPS_t = max(EPS_t, 0) × payout_t', mistakes: ['A payout above 100% for many years.', 'Ignoring that cash paid out cannot also fund growth or buybacks.'], src: ['damData'], research: 'Total return = price return + dividend yield. A high payout with high growth is usually inconsistent.' });
  g('dpsGrowth', { t: 'Dividend per share growth', what: 'The annual growth of the dividend per share.', why: 'With the growth method, DPS_t = DPS_0 × (1 + g)^t.', find: 'The company\'s dividend history (5- and 10-year DPS growth) and policy statements.',
    calc: 'DPS CAGR = (DPS now ÷ DPS n years ago)^(1/n) − 1.', forecast: 'Usually close to long-run EPS growth for a stable payout.', effect: 'Adds to total return only.', ex: '$1.00 growing 5%: 1.05, 1.10, 1.16, 1.22, 1.28. ' + ILL,
    formula: 'DPS_t = DPS_(t−1) × (1 + g_DPS)', mistakes: ['Growing dividends faster than earnings for many years.'], src: ['damData'], research: 'Dividend growth well above earnings growth raises the payout ratio until it becomes unsustainable.' });

  // ---------- multiples ----------
  const multCommon = 'Anchors: today\'s multiple (shown next to the input), the company\'s own 5–10 year range, peers on Trading Comps, and industry data (Damodaran). Multiples usually fall as growth slows: a company growing 25% at 40× rarely keeps 40× when growth falls to 8%.';
  g('pe', { t: 'Future P/E ratio', what: 'The price-to-earnings multiple you assume the market will pay at the end of each projection year: price ÷ diluted EPS.',
    why: 'P/E and EPS growth projections convert projected EPS into a price: price = EPS × P/E. It is an equity multiple, applied to earnings that belong to shareholders, so no debt adjustment is needed.',
    find: 'Today\'s P/E (price ÷ base-period diluted EPS). History: the stock\'s own P/E range (quote sites, Yahoo Finance). Peers: Trading Comps. Industry: Damodaran\'s P/E by industry.', calc: 'P/E = share price ÷ diluted EPS (TTM or forward). Use a trailing P/E with trailing EPS: the projected year-n EPS is the trailing EPS at the end of year n.',
    forecast: multCommon + ' Fundamentally, P/E rises with growth and return on capital and falls with risk (cost of equity).', effect: 'Proportional: 25× instead of 30× lowers the price by 16.7%. Multiple contraction can offset years of earnings growth.',
    ex: 'EPS $10 growing 10% to $16.11 in year 5: at 30× = $483; at 20× = $322. If today\'s price is $300 (30× EPS of $10), the 20× case returns only 1.4% a year despite 10% earnings growth. ' + ILL,
    formula: 'Price_t = EPS_t × P/E_t', mistakes: ['Applying a P/E to negative earnings.', 'Using a forward P/E with trailing EPS.', 'Holding a very high P/E constant while growth slows.'], src: ['damPE', 'damCh18', 'cfaMult'],
    research: 'A quick check: the PEG ratio (P/E ÷ growth in %) of about 1–2 is common for profitable growers; a PEG far above 2 in year 5 implies the market still expects high growth after your projection ends.' });
  g('evEbitda', { t: 'Future EV/EBITDA', what: 'Enterprise value ÷ EBITDA assumed at the end of each projection year.', why: 'An enterprise multiple: EV belongs to debt and equity holders, so the simulator subtracts debt and claims and adds cash before dividing by shares. It is useful when capital structures differ.',
    find: 'Today\'s EV/EBITDA, the company\'s range, Trading Comps peers, Damodaran\'s EV/EBITDA by industry.', calc: 'EV/EBITDA = (market cap + debt + other claims − cash) ÷ EBITDA.',
    forecast: multCommon, effect: 'The price moves by more than the multiple when the company has net debt, and by less when it has net cash.',
    ex: 'EBITDA 37,500 × 15 = EV 562,500; − debt 60,000 + cash 10,000 = equity 512,500; ÷ 2,000mm shares = $256.25. ' + ILL, formula: 'Price_t = (EBITDA_t × EV/EBITDA_t − debt_t − claims + cash_t) ÷ shares_t',
    mistakes: ['Multiplying EV/EBITDA by EBITDA and calling it the market cap (forgetting the bridge).', 'Mixing lease treatments between the multiple and the debt figure.'], src: ['damEbitda', 'cfaMult', 'ifrs16'], research: 'EV/EBITDA ignores capital intensity: two companies with the same multiple can have very different free cash flow.' });
  g('evEbit', { t: 'Future EV/EBIT', what: 'Enterprise value ÷ operating income.', why: 'An enterprise multiple that charges depreciation as a cost; better for capital-intensive businesses.', find: 'Today\'s EV/EBIT; Damodaran\'s value multiples by industry; Trading Comps.',
    calc: 'EV/EBIT = EV ÷ operating income.', forecast: multCommon, effect: 'As EV/EBITDA, with EBIT as the base.', ex: 'EBIT 22,500 × 20 = EV 450,000; − net debt 50,000 = 400,000; ÷ 2,000 = $200.00. ' + ILL,
    formula: 'Price_t = (EBIT_t × EV/EBIT_t − debt_t − claims + cash_t) ÷ shares_t', mistakes: ['Using EV/EBIT on a company with negative or tiny EBIT.'], src: ['damEbitda', 'cfaMult'], research: 'EV/EBIT ≈ EV/NOPAT × (1 − tax), so it links directly to return on capital and growth.' });
  g('evRev', { t: 'Future EV/Revenue', what: 'Enterprise value ÷ revenue.', why: 'Works when earnings are negative or not yet meaningful (young or cyclical companies). It is an enterprise multiple, so it goes through the equity bridge.',
    find: 'Today\'s EV/Revenue; Damodaran\'s EV/sales by industry; Trading Comps.', calc: 'EV/Revenue = EV ÷ revenue.', forecast: 'Tie it to the margin you expect: EV/Revenue = EV/EBITDA × EBITDA margin. A company growing into higher margins usually sees its EV/Revenue fall as profits arrive.',
    effect: 'Proportional to EV; price moves more with net debt.', ex: 'Revenue 50,000 × 4 = EV 200,000; + net cash 10,000 = 210,000; ÷ 1,500 = $140.00. ' + ILL, formula: 'Price_t = (Revenue_t × EV/Revenue_t − debt_t − claims + cash_t) ÷ shares_t',
    mistakes: ['Using a software company\'s EV/Revenue for a retailer (margins differ hugely).', 'Holding a high EV/Revenue while margins stay low.'], src: ['damPS', 'damCh20'], research: 'EV/Revenue implied = EV/EBITDA × EBITDA margin: check that the two are consistent in your scenarios.' });
  g('ps', { t: 'Future price/sales', what: 'Market capitalisation ÷ revenue (an equity multiple).', why: 'Like EV/Revenue but without the debt adjustment: price = revenue × P/S ÷ shares. Use it only with P/S data, never with EV/Revenue data.',
    find: 'Today\'s P/S; Damodaran\'s price-to-sales by industry.', calc: 'P/S = market cap ÷ revenue.', forecast: 'As EV/Revenue. Prefer EV/Revenue when debt or cash is large.', effect: 'Proportional to the price.',
    ex: 'Revenue 50,000 × 3 = 150,000 market cap; ÷ 1,500 = $100.00. ' + ILL, formula: 'Price_t = Revenue_t × P/S_t ÷ shares_t', mistakes: ['Applying an EV/Revenue multiple as if it were P/S (ignores debt).'], src: ['damPS'], research: 'P/S is distorted by leverage: two companies with the same operations and different debt have different P/S.' });
  g('pfcf', { t: 'Future price/free cash flow', what: 'Market capitalisation ÷ free cash flow (an equity multiple).', why: 'Values the cash the business generates rather than accounting earnings.', find: 'Today\'s P/FCF; history.',
    calc: 'P/FCF = market cap ÷ FCF. Strictly, FCF to equity is after interest; here FCF is operating cash flow − capex as reported (interest is already in operating cash flow under US GAAP).', forecast: 'Usually close to the P/E for mature companies whose FCF ≈ net income.',
    effect: 'Proportional.', ex: 'FCF 15,000 × 25 = 375,000 market cap; ÷ 2,000 = $187.50. ' + ILL, formula: 'Price_t = FCF_t × P/FCF_t ÷ shares_t', mistakes: ['Using it when FCF is negative or temporarily depressed by investment.'], src: ['damData'], research: 'Compare the FCF yield (1 ÷ P/FCF) with bond yields as a sanity check.' });

  // ---------- settings and concepts ----------
  g('method', { t: 'Projection method', what: 'How projected fundamentals become a price. Equity methods (P/E, EPS growth, P/S, P/FCF) multiply a measure that belongs to shareholders. Enterprise methods (EV/EBITDA, EV/EBIT, EV/Revenue) multiply a measure that belongs to all capital providers and then subtract debt and claims and add cash.',
    why: 'Different businesses suit different multiples: P/E for steady profits, EV/EBITDA when debt levels differ, EV/Revenue or P/S when profits are not yet positive.', find: 'Every method is calculated side by side on Year-by-Year Projections; the selected method feeds the dashboard and scenarios.',
    calc: 'P/E: Revenue × margin ÷ diluted shares × P/E. EPS: EPS₀ × (1 + g)^t × P/E. EV methods: (metric × multiple − debt − claims + cash) ÷ shares.', forecast: 'Pick the method analysts use for the industry; check the others for consistency.', effect: 'Methods disagree when their multiples imply different views; large gaps are flagged.',
    ex: 'For the same company, a 20× P/E and a 12× EV/EBITDA can give prices 20–30% apart; that gap shows the two multiples are not consistent with each other. ' + ILL, mistakes: ['Applying an EV multiple to net income or EPS.', 'Applying P/E to EBITDA.', 'Forgetting the equity bridge for EV methods.'], src: ['cfaMult', 'damCh18', 'damCh20'],
    research: 'Never mix numerators and denominators: EV goes with operating measures before interest (revenue, EBITDA, EBIT); market cap goes with measures after interest (net income, EPS, FCF to equity).' });
  g('years', { t: 'Projection period (1–10 years)', what: 'How many years ahead the price is projected.', why: 'Longer periods let growth compound but are less certain; the multiple at the end matters more the shorter the period.',
    find: '—', calc: 'Year t ends t years after the base period end.', forecast: '3–5 years is common for price targets; 10 years for thesis-level questions.', effect: 'More years at positive growth raise the projected price but the annualised return can still fall if the multiple contracts.',
    ex: 'At 10% EPS growth and a constant P/E, the price is 1.61× today\'s after 5 years and 2.59× after 10. ' + ILL, mistakes: ['Reading a 10-year projection with the same confidence as a 1-year one.'], src: ['cfaMult'], research: 'Uncertainty widens with time: compare the Bear–Bull range in year 1 and in year 10.' });
  g('waBasis', { t: 'Share count for EPS', what: 'EPS is reported on weighted-average diluted shares (the average count during the year). The default uses the average of the start and end counts; "end of year" uses the year-end count.',
    why: 'Matches how companies report EPS. EV, P/S and P/FCF prices always divide by the year-end count (a point in time).', find: '—', calc: 'Weighted-average ≈ (shares at start + shares at end) ÷ 2.', forecast: '—', effect: 'Small: with 2% annual dilution, end-of-year shares are about 1% higher than the average.',
    ex: '1,000mm → 1,020mm in a year: average 1,010mm; EPS on 50,000 $mm is $49.50 (average) vs $49.02 (end). ' + ILL, mistakes: ['Using the year-end count for EPS and the average for per-share equity.'], src: ['amzn10k'], research: '—' });
  g('weights', { t: 'Scenario probabilities', what: 'Your estimate of how likely each scenario is. They must add up to 100%.', why: 'Gives a probability-weighted expected price, which is more honest than a single Base case.',
    find: 'Judgement. Write the reasoning in each scenario\'s rationale.', calc: 'Expected price = Σ probability × scenario price.', forecast: '25/50/25 is a neutral starting point; skew it when you think risks are asymmetric.', effect: 'Shifts the expected price toward the scenario you weight more.',
    ex: '25% × $210 + 50% × $348 + 25% × $545 = $362.75. ' + ILL, mistakes: ['Probabilities that do not add up to 100%.', 'Treating the expected price as a forecast.'], src: ['cfaMult'], research: 'The spread between Bear and Bull is as informative as the expected price: it shows how much your answer depends on assumptions.' });
  g('reqReturn', { t: 'Required annual return', what: 'The annual return you require to hold the stock (often the cost of equity from the DCF\'s WACC builder).', why: 'Discounting the projected price and dividends back to today at this rate gives a value today that can be compared with the DCF value and the current price.',
    find: 'The DCF\'s cost of equity (WACC Builder), or your own hurdle rate.', calc: 'Value today = Σ DPS_t ÷ (1 + r)^h_t + Price_n ÷ (1 + r)^h_n, where h is years from the price date.', forecast: '—',
    effect: 'A higher required return lowers the value today.', ex: 'A $348 price in 4.92 years at 9%: 348 ÷ 1.09^4.92 = $227.74. ' + ILL, mistakes: ['Comparing a future price directly with today\'s DCF value without discounting it.'], src: ['cfaMult'], research: 'If the value today is above the current price, the projected return is above your required return.' });
  g('returns', { t: 'Upside and annualised return', what: 'Price return = projected price ÷ current price − 1. Annualised return (CAGR) = (projected ÷ current)^(1/years held) − 1. Total return adds dividends received; the IRR includes their timing.',
    why: 'Annualised returns let you compare horizons and with other investments.', find: 'Calculated.', calc: 'CAGR = (P_n ÷ P_0)^(1/h) − 1, with h = years from the price date to the end of year n. IRR solves 0 = −P_0 + Σ D_t ÷ (1 + r)^h_t + P_n ÷ (1 + r)^h_n.',
    forecast: '—', effect: '—', ex: '$220 → $348.13 over 4.92 years: (348.13 ÷ 220)^(1/4.92) − 1 = 9.8% a year. ' + ILL, mistakes: ['Dividing the total return by the number of years (ignores compounding).', 'Treating a projected return as an expected or guaranteed return.'], src: ['cfaMult'], research: 'Dividends are assumed paid at the end of each year and not reinvested in the IRR.' });
  g('reverse', { t: 'Reverse projection', what: 'Starts from a target price and solves for the assumption needed to reach it, one assumption at a time.', why: 'Shows what the market (or a price target) implicitly assumes, which is often easier to judge than a price.',
    find: '—', calc: 'Required EPS = target ÷ P/E. Required P/E = target ÷ projected EPS. Required margin = required EPS × shares ÷ revenue. Required growth = (required revenue ÷ starting revenue)^(1/n) − 1. Required EBITDA = (target × shares + debt + claims − cash) ÷ EV/EBITDA. Required EV/EBITDA = (target × shares + debt + claims − cash) ÷ EBITDA.',
    forecast: '—', effect: '—', ex: 'Target $400 at 20× P/E needs EPS of $20.00. ' + ILL, mistakes: ['Changing two assumptions at once and reading it as one answer.'], src: ['cfaMult'], research: 'Run the reverse projection on today\'s price with today\'s multiple to see the growth the market is pricing in.' });
  g('perYear', { t: 'Per-year assumptions', what: 'Every assumption can be one constant for all years or a value for each forecast year (an empty cell uses the constant).', why: 'Real forecasts fade: growth slows, margins expand, multiples compress.',
    find: '—', calc: 'Year t uses its own value when entered, otherwise the constant. The "fade" helper fills a straight line from the year-1 value to the final-year value.', forecast: 'Use per-year paths for anything that should change over time.', effect: 'Only the path to the final year matters for revenue and shares; only the final-year margin and multiple matter for that year\'s price.',
    ex: 'Growth fading 20% → 8% over five years: 20%, 17%, 14%, 11%, 8%. ' + ILL, mistakes: ['Leaving a per-year value in place after changing the constant (the per-year value wins).'], src: ['damGrowth'], research: '—' });
  g('leases', { t: 'Operating leases in the equity bridge', what: 'Whether operating lease liabilities count as debt when converting EV to equity value.', why: 'It must match how the multiple was measured. US GAAP EBITDA includes operating lease cost, so US EV/EBITDA multiples normally exclude operating leases from EV (the default).',
    find: 'Balance sheet: operating lease liabilities (current and non-current).', calc: 'Debt + operating leases (if included).', forecast: 'Held constant.', effect: 'Including leases lowers EV-method prices.', ex: '5,000 $mm of leases ÷ 1,000mm shares = $5.00 per share lower. ' + ILL,
    mistakes: ['Including leases in debt with an EBITDA that is before lease cost only under IFRS.'], src: ['ifrs16'], research: '—' });
  const ORDER = [['What it is', 'what'], ['Why analysts calculate it', 'why'], ['Where to find the figures', 'find'], ['How to calculate it', 'calc'], ['How to build a reasonable forecast', 'forecast'], ['How it affects the projected price', 'effect'], ['Numerical example', 'ex'], ['Common mistakes', 'mistakes'], ['Sources', 'src'], ['Analyst research notes', 'research']];
  return { S, G, ORDER };
})();
if (typeof module !== 'undefined') module.exports = SimHelp;
